const rules = $input.all().map(i => i.json);
const today = new Date().getDay(); // 0=Sun..6=Sat, matches recurring_zone_rules.days_of_week
const todayDate = new Date().toISOString().slice(0, 10);

const dueRules = rules.filter(r => Array.isArray(r.days_of_week) && r.days_of_week.includes(today));

if (dueRules.length === 0) return []; // nothing due today — workflow ends here, correctly

return [{ json: { dueRules, todayDate } }];

const { dueRules, todayDate } = $('Compute Due Rules').first().json;

const raw = $input.all().map(i => i.json);
const todaysJobs = Array.isArray(raw[0]) ? raw[0] : raw.filter(r => r && r.id);

const jobByFacility = {};
for (const j of todaysJobs) jobByFacility[j.facility_id] = j.id;

const seenFacilities = new Set();
const jobsToCreate = [];
for (const rule of dueRules) {
  if (jobByFacility[rule.facility_id] || seenFacilities.has(rule.facility_id)) continue;
  seenFacilities.add(rule.facility_id);
  jobsToCreate.push({
    facility_id: rule.facility_id,
    company_id: rule.company_id,
    scheduled_date: todayDate,
    status: 'scheduled',
    supervisor_id: rule.created_by,
  });
}

return [{ json: { dueRules, todayDate, jobByFacility, jobsToCreate } }];

const { dueRules, jobByFacility } = $('Resolve Jobs + Compute New Job Rows').first().json;

const raw = $input.all().map(i => i.json);
const newJobs = Array.isArray(raw[0]) ? raw[0] : raw.filter(r => r && r.id);

const resolvedJobByFacility = { ...jobByFacility };
for (const j of newJobs) resolvedJobByFacility[j.facility_id] = j.id;

const zoneRows = dueRules
  .map(r => ({
    job_id: resolvedJobByFacility[r.facility_id],
    zone_name: r.zone_name,
    cleaner_id: r.cleaner_id,
    notes: r.notes ?? null,
    status: 'not_started',
  }))
  .filter(z => !!z.job_id);

const jobIds = [...new Set(zoneRows.map(z => z.job_id))];

return [{ json: { zoneRows, jobIdsCsv: jobIds.join(',') } }];

const { zoneRows } = $('Build Zone Payload').first().json;

const raw = $input.all().map(i => i.json);
const existing = Array.isArray(raw[0]) ? raw[0] : raw.filter(r => r && r.job_id);

const existingKeys = new Set(existing.map(e => `${e.job_id}::${e.zone_name}::${e.cleaner_id}`));
const toInsert = zoneRows.filter(z => !existingKeys.has(`${z.job_id}::${z.zone_name}::${z.cleaner_id}`));

return [{ json: { toInsert } }];
